# create a new 'PVD Reader'
resultspvd = PVDReader(registrationName='Results.pvd', FileName='/u/guest/castro/GReS/Tests/Sedimentation/LinearSedimentation2D/Outputs/Results.pvd')
resultspvd.Set(
    CellArrays=['pressure', 'stress', 'strain', 'voidRate', 'porosity', 'conductivity', 'age', 'oedometricComp', 'Precon_stress', 'material01', 'material02', 'material03', 'material04', 'cellTag'],
    PointArrays=['compaction'],
    ColumnArrays=[],
)

# create a new 'Extract Selection'
removeBase = ExtractSelection(registrationName='RemoveBase', Input=resultspvd,
    Selection=selection_filter11449)
removeBase.Set(
    PreserveTopology=0,
    HyperTreeGridToUnstructuredGrid=0,
)

# create a new 'Warp By Scalar'
deformMesh = WarpByScalar(registrationName='DeformMesh', Input=removeBase)
deformMesh.Set(
    Scalars=['POINTS', 'compaction'],
    ScaleFactor=-1.0,
    Normal=[0.0, 0.0, 1.0],
    UseNormal=0,
    XYPlane=0,
    GenerateEnclosure=0,
)

# create a new 'Plot Over Line'
lineA = PlotOverLine(registrationName='Line A', Input=deformMesh)
lineA.Set(
    SamplingPattern='Sample Uniformly',
    Resolution=1000,
    PassPartialArrays=1,
    PassCellArrays=0,
    PassPointArrays=0,
    PassFieldArrays=1,
    ComputeTolerance=1,
    Tolerance=2.220446049250313e-16,
    Point1=[0.05, 1.5, 0.0],
    Point2=[0.05, 1.5, 3.0],
)

# create a new 'Plot Over Line'
lineB = PlotOverLine(registrationName='Line B', Input=deformMesh)
lineB.Set(
    SamplingPattern='Sample Uniformly',
    Resolution=1000,
    PassPartialArrays=1,
    PassCellArrays=0,
    PassPointArrays=0,
    PassFieldArrays=1,
    ComputeTolerance=1,
    Tolerance=2.220446049250313e-16,
    Point1=[9.95, 1.5, 0.0],
    Point2=[9.95, 1.5, 3.0],
)

# create a new 'Extract Selection'
clay = ExtractSelection(registrationName='Clay', Input=deformMesh,
    Selection=selection_filter16344)
clay.Set(
    PreserveTopology=0,
    HyperTreeGridToUnstructuredGrid=0,
)

# create a new 'Extract Selection'
peat = ExtractSelection(registrationName='Peat', Input=deformMesh,
    Selection=selection_filter16057)
peat.Set(
    PreserveTopology=0,
    HyperTreeGridToUnstructuredGrid=0,
)

# create a new 'Extract Selection'
silt = ExtractSelection(registrationName='Silt', Input=deformMesh,
    Selection=selection_filter16631)
silt.Set(
    PreserveTopology=0,
    HyperTreeGridToUnstructuredGrid=0,
)

